<?php require '_top.php';$msg='';if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_FILES['imagem'])){$f=$_FILES['imagem'];$allowed=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'];$mime=(new finfo(FILEINFO_MIME_TYPE))->file($f['tmp_name']);if($f['error']===UPLOAD_ERR_OK&&$f['size']<=2*1024*1024&&isset($allowed[$mime])){$name=bin2hex(random_bytes(16)).'.'.$allowed[$mime];$dir=__DIR__.'/../img/uploads';if(!is_dir($dir))mkdir($dir,0755,true);move_uploaded_file($f['tmp_name'],$dir.'/'.$name);$msg='Imagem enviada: img/uploads/'.$name;}else $msg='Envie JPEG, PNG ou WebP de no máximo 2 MB.';}?><h1>Upload de imagem</h1><p>Use imagens apenas quando necessárias aos conteúdos. São aceitos JPEG, PNG e WebP (até 2 MB).</p><?php if($msg):?><p class="notice"><?=e($msg)?></p><?php endif?><form class="contact" method="post" enctype="multipart/form-data"><input type="file" name="imagem" accept="image/jpeg,image/png,image/webp" required><button class="button">Enviar imagem</button></form><?php require '_bottom.php'; ?>
